%[text] # Observations
%[text] - Just a Code block
%[text] - Uses a nested loop: outer loop over `t`, inner loop stepping through each element of `x` — correct result, but the inner loop is unnecessary since MATLAB evaluates the formula over an entire vector at once
%[text] - Good example of "thinking like C/Python" vs. "thinking in MATLAB" — loop-over-elements is familiar from other languages but fights the tool
%[text] - Worth benchmarking: for 100 points it doesn't matter, but for a large grid it would be orders of magnitude slower
%[text] - Standout choice: uses `text(X(end), V(end), sprintf(' t = %.0fs', t))` to label each curve at its endpoint rather than a `legend()` — the label sits right on the line, which is often cleaner for data that fans out like this
%[text] - Shows awareness of MATLAB's annotation tools beyond what was explicitly covered \
%%
figure(1)
clf() %[output:5d00ca16]
figure(2)
clf() %[output:5d00ca16]
%Plotting fluid velocities and acceleration in a nozzle
X = linspace(0,4,100); %Distance from nozzle start to exit
for t=0:10:30 %[output:group:5814830f]
    % for ii=1:length(X)
    %     V(ii) = ((10+0.2.*t)*pi)./((pi/4)*(4-0.25.*(X(ii)))^2); %Velocity as a function of distance and time     
    %     A(ii) = (0.5/(4-0.25.*X(ii))^2)+(0.5*(24+0.5.*t)^2)./(2-0.125*X(ii))^5; %Acceleration as a function of distance and time
    % end
    V = ((10+0.2.*t)*pi)./((pi/4)*(4-0.25.*(X)).^2); %Velocity as a function of distance and time     

    figure(1)
    hold on %[output:5d00ca16]
    xlabel('Distance along nozzle [m]')
    ylabel('Fluid velocity [m/s]')
    plot(X,V)
    text(X(end), V(end), sprintf(' t = %.0fs', t))
    title('Velocity vs Distance')
    figure(2)
    hold on
    xlabel('Distance along nozzle [m]')
    ylabel('Fluid acceleration [m/s^2]')
    plot(X,A)
    text(X(end), A(end), sprintf(' t = %.0fs', t))
    title('Acceleration vs Distance')
end %[output:group:5814830f]



